const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let draft,tab='settings',editing=null,dirty=false;
const collections={topics:'Libro de temas',units:'Unidades',resources:'Materiales y actividades',events:'Calendario',gallery:'Galería',partners:'Colaboradores',news:'Noticias y actualidad'};
const pageOptions={material:'Material de consulta',practicos:'Trabajos prácticos',proyecto:'Proyecto integrador',inet:'INET',movimiento:'Hormigón en movimiento'};
const status=(s,error=false)=>{const el=document.getElementById('status');el.textContent=s;el.classList.toggle('error',error)};
const field=(name,label,value='',type='text')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${name==='title'?'required':''}></label>`;
const area=(name,label,value='')=>`<label>${esc(label)}<textarea name="${name}">${esc(value)}</textarea></label>`;
const select=(name,label,options,value)=>`<label>${esc(label)}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
function mark(){dirty=true;status('Hay cambios en el editor. Guardá el borrador antes de abrir la vista previa.');}
function settings(){const s=draft.settings;return `<h2>Inicio y datos generales</h2><p class="muted">Los enlaces vacíos se muestran como pendientes, sin dirigir a cuentas ajenas.</p><form id="settings-form"><div class="form-grid">${field('siteName','Nombre del sitio',s.siteName)}${field('school','Institución',s.school)}${field('specialty','Especialidad',s.specialty)}${field('tagline','Frase principal',s.tagline)}</div>${area('intro','Descripción del inicio',s.intro)}<div class="form-grid">${field('instagram','Enlace a Instagram',s.instagram,'url')}${field('portal','Enlace al portal institucional',s.portal,'url')}${field('email','Correo de contacto',s.email,'email')}</div><button class="btn" type="submit">Aplicar al borrador</button></form>`}
function pageEditor(){return `<h2>Títulos de las páginas</h2><form id="pages-form">${Object.entries(draft.pages).map(([k,p])=>`<fieldset><legend>${esc(p.title)}</legend>${field(k+'-title','Título',p.title)}${area(k+'-description','Descripción',p.description)}</fieldset>`).join('')}<button class="btn" type="submit">Aplicar al borrador</button></form>`}
function collection(){const xs=draft[tab];return `<div class="section-head"><div><h2>${collections[tab]}</h2><p class="muted">${xs.length} registros · el orden de la galería y colaboradores sigue esta lista.</p></div><button class="btn" id="new-entry">Agregar ${tab==='gallery'?'imágenes':'registro'} +</button></div>${tab==='gallery'?'<p class="small">Podés seleccionar varias imágenes juntas. Cada una crea una ficha editable. Formatos: JPG, PNG o WebP, hasta 10 MB por imagen.</p>':''}<div>${xs.map((x,i)=>`<div class="entry"><div>${x.image?`<img class="editor-image" src="${esc(ContentStore.safeImage(x.image))}" alt="">`:''}<strong>${esc(x.title)}</strong><div class="small">${esc(x.category||x.date||x.page||'')}${x.example?' · Ejemplo':''}</div></div><div class="entry-actions"><button class="mini" data-edit="${i}">Editar</button><button class="mini" data-move="${i}" data-dir="-1" ${i===0?'disabled':''} aria-label="Subir ${esc(x.title)}">↑</button><button class="mini" data-move="${i}" data-dir="1" ${i===xs.length-1?'disabled':''} aria-label="Bajar ${esc(x.title)}">↓</button><button class="mini danger" data-delete="${i}">Eliminar</button></div></div>`).join('')||'<div class="empty">No hay registros. Agregá el primero para preparar esta página.</div>'}</div><div id="entry-editor"></div>`}
function entryForm(x={}){return `<fieldset><legend>${editing===null?'Nuevo registro':'Editar registro'}</legend><form id="entry-form">${field('title','Título',x.title)}${area('description','Descripción',x.description)}${['topics','events','news'].includes(tab)?field('date','Fecha',x.date,'date'):''}${tab==='news'?`${select('category','Categoría',['Hormigón y materiales','Estructuras y obras','Normativa','Innovación','Aula y visitas'].map(t=>[t,t]),x.category||'Hormigón y materiales')}${field('source','Nombre de la fuente',x.source)}${area('body','Texto completo de la nota (opcional)',x.body)}<label>Imagen de la noticia (opcional)<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label>${x.image?'<label><input name="removeImage" type="checkbox"> Quitar imagen actual</label>':''}`:''}${tab==='resources'?select('page','Página de destino',Object.entries(pageOptions),x.page||'material'):''}${tab==='gallery'?`<div class="form-grid">${select('category','Categoría',['Planos y CAD','Maquetas','Expo'].map(t=>[t,t]),x.category||'Planos y CAD')}${field('course','Curso',x.course)}${field('year','Año',x.year)}</div><label>${editing===null?'Seleccionar imágenes (una o varias)':'Reemplazar imagen'}<input id="upload-images" type="file" accept="image/jpeg,image/png,image/webp" ${editing===null?'multiple required':''}></label>${x.image?'<p class="small">La imagen actual se conserva si no seleccionás otra.</p>':''}`:''}${tab==='partners'?`${select('category','Tipo de colaborador',['Estudios de ingeniería','Hormigoneras','Corralones'].map(t=>[t,t]),x.category||'Estudios de ingeniería')}<div class="form-grid">${field('email','Correo',x.email,'email')}${field('phone','Teléfono / WhatsApp',x.phone)}${field('address','Dirección',x.address)}</div><label>Imagen de portada<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><label>Logo<input name="logoFile" type="file" accept="image/jpeg,image/png,image/webp"></label>`:''}${tab!=='gallery'?field('url','Enlace al material o sitio (opcional)',x.url,'url'):''}${['units','topics','resources','events'].includes(tab)?`<label><input name="example" type="checkbox" ${x.example?'checked':''}> Marcar como contenido de ejemplo</label>`:''}<div class="actions"><button class="btn" type="submit">Aplicar al borrador</button><button class="btn secondary" id="cancel-entry" type="button">Cancelar</button></div></form></fieldset>`}
async function imageData(f){if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024)throw Error('Usá JPG, PNG o WebP de hasta 10 MB.');const src=URL.createObjectURL(f);try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('No se pudo leer la imagen.'));img.src=src});const ratio=Math.min(1,1800/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*ratio));c.height=Math.max(1,Math.round(img.height*ratio));c.getContext('2d').drawImage(img,0,0,c.width,c.height);return c.toDataURL('image/webp',.9)}finally{URL.revokeObjectURL(src)}}
function render(){document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===tab)));const panel=document.getElementById('admin-panel');panel.innerHTML=tab==='settings'?settings():tab==='pages'?pageEditor():collection();if(tab==='settings'){document.getElementById('settings-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);for(const k of Object.keys(draft.settings))draft.settings[k]=String(f.get(k)||'').trim();mark()}}else if(tab==='pages'){document.getElementById('pages-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);for(const k of Object.keys(draft.pages)){draft.pages[k].title=String(f.get(k+'-title'));draft.pages[k].description=String(f.get(k+'-description'))}mark()}}else{document.getElementById('new-entry').onclick=()=>openEntry(null);document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEntry(Number(b.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.delete);if(confirm('¿Eliminar «'+draft[tab][i].title+'» del borrador?')){draft[tab].splice(i,1);mark();render()}});document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.move),j=i+Number(b.dataset.dir);[draft[tab][i],draft[tab][j]]=[draft[tab][j],draft[tab][i]];mark();render()})}}
function openEntry(i){editing=i;const el=document.getElementById('entry-editor');el.innerHTML=entryForm(i===null?{}:draft[tab][i]);document.getElementById('cancel-entry').onclick=()=>{el.innerHTML=''};document.getElementById('entry-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const f=new FormData(e.target),old=i===null?{}:draft[tab][i];const x={...old,id:old.id||crypto.randomUUID(),title:String(f.get('title')).trim(),description:String(f.get('description')||'').trim()};for(const k of ['date','page','category','course','year','email','phone','address','url','source','body'])if(f.has(k))x[k]=String(f.get(k)||'').trim();x.example=f.get('example')==='on';if(tab==='gallery'){const files=[...document.getElementById('upload-images').files];if(i===null&&!files.length)throw Error('Seleccioná al menos una imagen.');const prepared=[];for(const file of files)prepared.push({file,data:await imageData(file)});if(i===null){for(const {file,data}of prepared)draft.gallery.push({...x,id:crypto.randomUUID(),title:files.length>1?x.title+' · '+file.name.replace(/\.[^.]+$/,''):x.title,image:data})}else{if(prepared.length)x.image=prepared[0].data;draft.gallery[i]=x}}else{if(tab==='news'){const file=f.get('photo');if(file&&file.size)x.image=await imageData(file);else if(f.get('removeImage')==='on')delete x.image}if(tab==='partners'){for(const [input,key]of [['photo','image'],['logoFile','logo']]){const file=f.get(input);if(file&&file.size)x[key]=await imageData(file)}}if(i===null)draft[tab].push(x);else draft[tab][i]=x}mark();render()}catch(err){status(err.message,true);button.disabled=false}};el.scrollIntoView({behavior:'smooth',block:'start'});el.querySelector('input').focus()}
async function save(){await ContentStore.save(draft);dirty=false;status('Borrador guardado en este navegador. Todavía no está publicado.');}
async function init(){try{draft=ContentStore.validate(await ContentStore.get()||await ContentStore.seed());document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;editing=null;render()});document.getElementById('save').onclick=async()=>{try{await save()}catch(e){status('No se pudo guardar: '+e.message,true)}};document.getElementById('preview').onclick=async e=>{e.preventDefault();try{await save();location.href='index.html?preview=1'}catch(err){status(err.message,true)}};document.getElementById('export').onclick=async()=>{try{await save();const url=URL.createObjectURL(new Blob([JSON.stringify(ContentStore.validate(draft),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='content.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('Contenido exportado. Para publicarlo, reemplazá dist/data/content.json en el repositorio y desplegá el sitio.')}catch(err){status(err.message,true)}};document.getElementById('import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>40*1024*1024)throw Error('El archivo supera 40 MB.');const next=ContentStore.validate(JSON.parse(await file.text()));if(!confirm('¿Reemplazar el borrador con el contenido del archivo?'))return;await ContentStore.save(next);draft=next;dirty=false;render();status('Contenido importado y guardado como borrador.')}catch(err){status('No se pudo importar: '+err.message,true)}finally{e.target.value=''}};render();window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}})}catch(err){status(err.message,true)}}
init();
